  Lemma c1_run : forall regs,
    getr regs 11 = Z_to_bv 64 0x146490 -> getr regs 12 = Z_to_bv 64 p1 -> getr regs 13 = Z_to_bv 64 p2 -> getr regs 14 = Z_to_bv 64 n -> getr regs 2 = sp -> getr regs 1 = ra ->
    exists regs',
