Theorem mic_run_pk : forall (mem0 rom : word -> option byte) (sp ra : word) (p1 p2 n s res kS fS lS faS laS kD fD lD faD laD : Z),
  bv_unsigned sp = s ->
  fS = (SB + p1 / 8)%Z -> lS = (SB + (p1 + n - 1) / 8)%Z -> faS = (fS - fS mod 8)%Z -> laS = (lS - lS mod 8)%Z ->
  fD = (SB + p2 / 8)%Z -> lD = (SB + (p2 + n - 1) / 8)%Z -> faD = (fD - fD mod 8)%Z -> laD = (lD - lD mod 8)%Z ->
  (0 <= n <= 2 ^ 40)%Z -> in_app8 p1 n -> in_app8 p2 n ->
  ((0x1000000 <= s - 2264)%Z /\ (s < 2 ^ 64)%Z) -> (lS + 8 <= s - 2264)%Z -> (lD + 8 <= s - 2264)%Z ->
  store_ok ASEGS mem0 (Z_to_bv 64 (s - 2264)) 2264%nat = true -> ret_ok ra -> rt_layout_globs mem0 -> mcmp_icpt_globs mem0 ->
  ((0 < n)%Z -> forall x : word, (fS <= bv_unsigned x < lS)%Z -> mem0 x = Some (Z_to_bv 8 0)) ->
  ((0 < n)%Z -> mem0 (Z_to_bv 64 lS) = Some (Z_to_bv 8 kS)) -> (kS = 0%Z \/ ((p1 + n - 1) mod 8 < kS <= 7)%Z) ->
  ((0 < n <= 64)%Z -> exists w0 w1, rdn ASEGS mem0 (Z_to_bv 64 faS) 8%nat = Some w0 /\ rdn ASEGS mem0 (Z_to_bv 64 laS) 8%nat = Some w1) ->
  ((0 < n)%Z -> forall x : word, (fD <= bv_unsigned x < lD)%Z -> mem0 x = Some (Z_to_bv 8 0)) ->
  ((0 < n)%Z -> mem0 (Z_to_bv 64 lD) = Some (Z_to_bv 8 kD)) -> (kD = 0%Z \/ ((p2 + n - 1) mod 8 < kD <= 7)%Z) ->
  ((0 < n <= 64)%Z -> exists w0 w1, rdn ASEGS mem0 (Z_to_bv 64 faD) 8%nat = Some w0 /\ rdn ASEGS mem0 (Z_to_bv 64 laD) 8%nat = Some w1) ->
  (forall regs M, (forall x : word, (bv_unsigned x < s - 2264 \/ s <= bv_unsigned x)%Z -> M x = mem0 x) -> mem_grows mem0 M ->
    getr regs 10 = Z_to_bv 64 p1 -> getr regs 11 = Z_to_bv 64 p2 -> getr regs 12 = Z_to_bv 64 n -> getr regs 2 = Z_to_bv 64 (s - 2192) -> getr regs 1 = (0x6bcd8 : word) ->
    exists regs' M',
      msteps ASEGS (mkst regs (0x146490 : word) M rom) (mkst regs' (0x6bcd8 : word) M' rom)
      /\ getr regs' 10 = Z_to_bv 64 res /\ keeps_cs regs regs'
      /\ (forall x : word, (bv_unsigned x < s - 2264 \/ s - 2192 <= bv_unsigned x)%Z -> M' x = M x) /\ mem_grows M M') ->
  forall regs,
    getr regs 11 = Z_to_bv 64 0x146490 -> getr regs 12 = Z_to_bv 64 p1 -> getr regs 13 = Z_to_bv 64 p2 -> getr regs 14 = Z_to_bv 64 n -> getr regs 2 = sp -> getr regs 1 = ra ->
    exists regs' Mj,
      msteps ASEGS (mkst regs (0x6bbb8 : word) mem0 rom) (mkst regs' ra Mj rom)
